UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "All": {
        "Claimed": "WITH d1 AS (SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND mappingtype = ''Workflow''), workflowkeys AS (SELECT workflowkey FROM ui.workflowmasters WHERE (workflowid IN (SELECT mappingid FROM d1) OR -1 IN (SELECT mappingid FROM d1)) AND itenantid = :tenantid AND is_filter_display = true) select task.name_ as \\"Stage\\", cuser.email_ as \\"Claimed By\\", hiproinst.start_time_ \\"Created Date\\", CASE WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Status\\", pdef.name_ as \\"Case Type\\", CASE WHEN task.assignee_ is not null THEN oplog.time_ ELSE null END  as \\"Claimed On\\", null as \\"Payer\\", null as  \\"Payee\\", null as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\" , null as  \\"Closed Date\\" , null as  \\"Closed By\\", basedon.text_ AS \\"Alert Type\\", address.text_ AS \\"Address\\" FROM camunda.act_ru_task task LEFT JOIN camunda.act_id_user cuser ON task.assignee_ = cuser.id_ LEFT JOIN camunda.act_re_procdef pdef ON pdef.id_ = task.proc_def_id_ LEFT JOIN camunda.act_hi_procinst hiproinst ON hiproinst.proc_inst_id_ = task.proc_inst_id_ LEFT JOIN camunda.act_hi_detail oplog ON oplog.id_ = (SELECT id_ FROM camunda.act_hi_detail WHERE proc_inst_id_ = task.proc_inst_id_ AND name_ = ''userActivity'' ORDER BY time_ DESC LIMIT 1) LEFT JOIN camunda.act_ru_variable TicketID ON TicketID.proc_inst_id_ = task.proc_inst_id_ AND TicketID.name_ = ''TicketID'' LEFT JOIN camunda.act_ru_variable Alert ON Alert.proc_inst_id_ = task.proc_inst_id_ AND Alert.name_ = ''Alert'' left JOIN camunda.act_hi_varinst basedon ON basedon.proc_inst_id_ = hiproinst.proc_inst_id_ AND basedon.name_ = ''basedon'' left JOIN camunda.act_hi_varinst address ON address.proc_inst_id_ = hiproinst.proc_inst_id_ AND address.name_ = ''address'' WHERE (hiproinst.start_time_ between :StartDate AND  :EndDate) AND task.assignee_ IS NOT NULL AND hiproinst.proc_def_key_ IN (SELECT workflowkey FROM workflowkeys) AND hiproinst.tenant_id_ = :tenantidstr LIMIT 25000;",
        "Unclaimed": "WITH d1 AS (SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND mappingtype = ''Workflow''), workflowkeys AS (SELECT workflowkey FROM ui.workflowmasters WHERE (workflowid IN (SELECT mappingid FROM d1) OR -1 IN (SELECT mappingid FROM d1)) AND itenantid = :tenantid AND is_filter_display = true) select task.name_ as \\"Stage\\", cuser.email_ as \\"Claimed By\\", hiproinst.start_time_ \\"Created Date\\", CASE WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Status\\", pdef.name_ as \\"Case Type\\", null as \\"Claimed On\\", null as \\"Payer\\", null as \\"Payee\\", null as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\" , null as  \\"Closed Date\\" ,null as  \\"Closed By\\", basedon.text_ AS \\"Alert Type\\", address.text_ AS \\"Address\\" from camunda.act_ru_task task right join camunda.act_re_procdef pdef on pdef.id_ = task.proc_def_id_  left join camunda.act_id_user cuser on task.assignee_=cuser.id_ right join camunda.act_ru_variable  TicketID on TicketID.proc_inst_id_ = task.proc_inst_id_ and TicketID.name_ = ''TicketID'' full outer join camunda.act_ru_variable Alert on Alert.proc_inst_id_ = task.proc_inst_id_ and Alert.name_ = ''Alert'' inner join  camunda.act_hi_procinst hiproinst  on hiproinst.proc_inst_id_ = task.proc_inst_id_  left JOIN camunda.act_hi_varinst basedon ON basedon.proc_inst_id_ = hiproinst.proc_inst_id_ AND basedon.name_ = ''basedon'' left JOIN camunda.act_hi_varinst address ON address.proc_inst_id_ = hiproinst.proc_inst_id_ AND address.name_ = ''address'' where (hiproinst.start_time_ between :StartDate AND  :EndDate) and task.assignee_ is null and hiproinst.proc_def_key_ in (SELECT workflowkey FROM workflowkeys) and hiproinst.tenant_id_= :tenantidstr limit 25000",
        "All": " WITH d1 AS (SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND mappingtype = ''Workflow''), workflowkeys AS (SELECT workflowkey FROM ui.workflowmasters WHERE (workflowid IN (SELECT mappingid FROM d1) OR -1 IN (SELECT mappingid FROM d1)) AND itenantid = :tenantid AND is_filter_display = true) SELECT CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ IS NOT NULL THEN clsuser.email_ ELSE ''Auto Closed'' END ELSE NULL END AS \\"Closed By\\", basedon.text_ AS \\"Alert Type\\", address.text_ as \\"Address\\", hiproinst.end_time_ AS \\"Closed Date\\", CASE WHEN hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END AS \\"Stage\\", cuser.email_ AS \\"Claimed By\\", hiproinst.start_time_ AS \\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN ''Closed'' WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \\"Status\\", pdef.name_ AS \\"Case Type\\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \\"Claimed On\\", null AS \\"Payer\\", null AS \\"Payee\\", null AS \\"Amount\\", ticketid.long_ AS \\"Case ID\\", alert.text_ AS \\"Alert\\" FROM camunda.act_hi_procinst hiproinst left OUTER JOIN camunda.act_re_procdef pdef ON pdef.id_ = hiproinst.proc_def_id_ left OUTER JOIN camunda.act_ru_task task ON task.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN camunda.act_id_user cuser ON cuser.id_ = task.assignee_ FULL OUTER JOIN camunda.act_hi_detail oplog ON oplog.id_ = (SELECT id_ FROM camunda.act_hi_detail WHERE proc_inst_id_ = task.proc_inst_id_ AND name_ = ''userActivity'' ORDER BY time_ DESC LIMIT 1) FULL OUTER JOIN camunda.act_hi_taskinst closedby ON closedby.id_ = (SELECT id_ FROM camunda.act_hi_taskinst WHERE proc_inst_id_ = hiproinst.proc_inst_id_ ORDER BY end_time_ DESC LIMIT 1) LEFT JOIN camunda.act_id_user clsuser ON clsuser.id_ = closedby.assignee_ left JOIN camunda.act_hi_varinst basedon ON basedon.proc_inst_id_ = hiproinst.proc_inst_id_ AND basedon.name_ = ''basedon'' left JOIN camunda.act_hi_varinst address ON address.proc_inst_id_ = hiproinst.proc_inst_id_ AND address.name_ = ''address'' FULL OUTER JOIN camunda.act_hi_varinst ticketid ON ticketid.proc_inst_id_ = hiproinst.proc_inst_id_ AND ticketid.name_ = ''TicketID'' FULL OUTER JOIN camunda.act_hi_varinst alert ON alert.proc_inst_id_ = hiproinst.proc_inst_id_ AND alert.name_ = ''Alert'' WHERE (hiproinst.start_time_ between :StartDate AND  :EndDate ) AND hiproinst.state_ != ''EXTERNALLY_TERMINATED'' AND hiproinst.proc_def_key_ IN (SELECT workflowkey FROM workflowkeys) AND hiproinst.tenant_id_ = :tenantidstr LIMIT 25000;",
        "Closed": " WITH d1 AS (SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND mappingtype = ''Workflow''), workflowkeys AS (SELECT workflowkey FROM ui.workflowmasters WHERE (workflowid IN (SELECT mappingid FROM d1) OR -1 IN (SELECT mappingid FROM d1)) AND itenantid = :tenantid AND is_filter_display = true) SELECT CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ IS NOT NULL THEN clsuser.email_ ELSE ''Auto Closed'' END ELSE NULL END AS \\"Closed By\\", basedon.text_ AS \\"Alert Type\\", address.text_ AS \\"Address\\", hiproinst.end_time_ AS \\"Closed Date\\", CASE WHEN hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END AS \\"Stage\\", cuser.email_ AS \\"Claimed By\\", hiproinst.start_time_ AS \\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN ''Closed'' WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \\"Status\\", pdef.name_ AS \\"Case Type\\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \\"Claimed On\\", null AS \\"Payer\\", null AS \\"Payee\\", null AS \\"Amount\\", ticketid.long_ AS \\"Case ID\\", alert.text_ AS \\"Alert\\" FROM camunda.act_hi_procinst hiproinst left OUTER JOIN camunda.act_re_procdef pdef ON pdef.id_ = hiproinst.proc_def_id_ left OUTER JOIN camunda.act_ru_task task ON task.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN camunda.act_id_user cuser ON cuser.id_ = task.assignee_ FULL OUTER JOIN camunda.act_hi_detail oplog ON oplog.id_ = (SELECT id_ FROM camunda.act_hi_detail WHERE proc_inst_id_ = task.proc_inst_id_ AND name_ = ''userActivity'' ORDER BY time_ DESC LIMIT 1) FULL OUTER JOIN camunda.act_hi_taskinst closedby ON closedby.id_ = (SELECT id_ FROM camunda.act_hi_taskinst WHERE proc_inst_id_ = hiproinst.proc_inst_id_ ORDER BY end_time_ DESC LIMIT 1) LEFT JOIN camunda.act_id_user clsuser ON clsuser.id_ = closedby.assignee_ left JOIN camunda.act_hi_varinst basedon ON basedon.proc_inst_id_ = hiproinst.proc_inst_id_ AND basedon.name_ = ''basedon'' left JOIN camunda.act_hi_varinst address ON address.proc_inst_id_ = hiproinst.proc_inst_id_ AND address.name_ = ''address'' FULL OUTER JOIN camunda.act_hi_varinst ticketid ON ticketid.proc_inst_id_ = hiproinst.proc_inst_id_ AND ticketid.name_ = ''TicketID'' FULL OUTER JOIN camunda.act_hi_varinst alert ON alert.proc_inst_id_ = hiproinst.proc_inst_id_ AND alert.name_ = ''Alert'' WHERE (hiproinst.start_time_ between :StartDate AND  :EndDate ) AND hiproinst.state_ = ''COMPLETED'' AND hiproinst.proc_def_key_ IN (SELECT workflowkey FROM workflowkeys) AND hiproinst.tenant_id_ = :tenantidstr LIMIT 25000;"
    },
    "Other": {
        "Claimed": "select task.name_ as \\"Stage\\", cuser.email_ as \\"Claimed By\\", hiproinst.start_time_ \\"Created Date\\", CASE WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Status\\", pdef.name_ as \\"Case Type\\", CASE WHEN task.assignee_ is not null THEN oplog.time_ ELSE null END  as \\"Claimed On\\", null as \\"Payer\\", null as  \\"Payee\\", null as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\" , null as  \\"Closed Date\\" , null as  \\"Closed By\\", basedon.text_ AS \\"Alert Type\\", address.text_ AS \\"Address\\" FROM camunda.act_ru_task task LEFT JOIN camunda.act_id_user cuser ON task.assignee_ = cuser.id_ LEFT JOIN camunda.act_re_procdef pdef ON pdef.id_ = task.proc_def_id_ LEFT JOIN camunda.act_hi_procinst hiproinst ON hiproinst.proc_inst_id_ = task.proc_inst_id_ LEFT JOIN camunda.act_hi_detail oplog ON oplog.id_ = (SELECT id_ FROM camunda.act_hi_detail WHERE proc_inst_id_ = task.proc_inst_id_ AND name_ = ''userActivity'' ORDER BY time_ DESC LIMIT 1) LEFT JOIN camunda.act_ru_variable TicketID ON TicketID.proc_inst_id_ = task.proc_inst_id_ AND TicketID.name_ = ''TicketID'' LEFT JOIN camunda.act_ru_variable Alert ON Alert.proc_inst_id_ = task.proc_inst_id_ AND Alert.name_ = ''Alert'' left JOIN camunda.act_hi_varinst basedon ON basedon.proc_inst_id_ = hiproinst.proc_inst_id_ AND basedon.name_ = ''basedon'' left JOIN camunda.act_hi_varinst address ON address.proc_inst_id_ = hiproinst.proc_inst_id_ AND address.name_ = ''address''  WHERE (hiproinst.start_time_ between :StartDate AND  :EndDate) AND task.proc_def_id_ in (SELECT id_ FROM camunda.act_re_procdef where key_ = :CaseType and tenant_id_= :tenantidstr) and task.assignee_ IS NOT NULL LIMIT 25000;", 
        "Unclaimed": "select task.name_ as \\"Stage\\", cuser.email_ as \\"Claimed By\\", hiproinst.start_time_ \\"Created Date\\", CASE WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Status\\", pdef.name_ as \\"Case Type\\", null as \\"Claimed On\\", null as \\"Payer\\", null as \\"Payee\\", null as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\" , null as  \\"Closed Date\\" ,null as  \\"Closed By\\", basedon.text_ AS \\"Alert Type\\", address.text_ AS \\"Address\\" from camunda.act_ru_task task right join camunda.act_re_procdef pdef on pdef.id_ = task.proc_def_id_  left join camunda.act_id_user cuser on task.assignee_=cuser.id_ right join camunda.act_ru_variable  TicketID on TicketID.proc_inst_id_ = task.proc_inst_id_ and TicketID.name_ = ''TicketID'' full outer join camunda.act_ru_variable Alert on Alert.proc_inst_id_ = task.proc_inst_id_ and Alert.name_ = ''Alert'' inner join  camunda.act_hi_procinst hiproinst  on hiproinst.proc_inst_id_ = task.proc_inst_id_  left JOIN camunda.act_hi_varinst basedon ON basedon.proc_inst_id_ = hiproinst.proc_inst_id_ AND basedon.name_ = ''basedon'' left JOIN camunda.act_hi_varinst address ON address.proc_inst_id_ = hiproinst.proc_inst_id_ AND address.name_ = ''address'' where (hiproinst.start_time_ between :StartDate AND  :EndDate) and task.proc_def_id_ in (SELECT id_ FROM camunda.act_re_procdef where key_ = :CaseType and tenant_id_= :tenantidstr) and task.assignee_ is null limit 25000",
        "All": "SELECT CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ IS NOT NULL THEN clsuser.email_ ELSE ''Auto Closed'' END ELSE NULL END AS \\"Closed By\\", basedon.text_ AS \\"Alert Type\\", address.text_ AS \\"Address\\", hiproinst.end_time_ AS \\"Closed Date\\", CASE WHEN hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END AS \\"Stage\\", cuser.email_ AS \\"Claimed By\\", hiproinst.start_time_ AS \\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN ''Closed'' WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \\"Status\\", pdef.name_ AS \\"Case Type\\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \\"Claimed On\\", null AS \\"Payer\\", null AS \\"Payee\\", null AS \\"Amount\\", ticketid.long_ AS \\"Case ID\\", alert.text_ AS \\"Alert\\" FROM camunda.act_hi_procinst hiproinst left OUTER JOIN camunda.act_re_procdef pdef ON pdef.id_ = hiproinst.proc_def_id_ left OUTER JOIN camunda.act_ru_task task ON task.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN camunda.act_id_user cuser ON cuser.id_ = task.assignee_ FULL OUTER JOIN camunda.act_hi_detail oplog ON oplog.id_ = (SELECT id_ FROM camunda.act_hi_detail WHERE proc_inst_id_ = task.proc_inst_id_ AND name_ = ''userActivity'' ORDER BY time_ DESC LIMIT 1) FULL OUTER JOIN camunda.act_hi_taskinst closedby ON closedby.id_ = (SELECT id_ FROM camunda.act_hi_taskinst WHERE proc_inst_id_ = hiproinst.proc_inst_id_ ORDER BY end_time_ DESC LIMIT 1) LEFT JOIN camunda.act_id_user clsuser ON clsuser.id_ = closedby.assignee_ left JOIN camunda.act_hi_varinst basedon ON basedon.proc_inst_id_ = hiproinst.proc_inst_id_ AND basedon.name_ = ''basedon'' left JOIN camunda.act_hi_varinst address ON address.proc_inst_id_ = hiproinst.proc_inst_id_ AND address.name_ = ''address'' FULL OUTER JOIN camunda.act_hi_varinst ticketid ON ticketid.proc_inst_id_ = hiproinst.proc_inst_id_ AND ticketid.name_ = ''TicketID'' FULL OUTER JOIN camunda.act_hi_varinst alert ON alert.proc_inst_id_ = hiproinst.proc_inst_id_ AND alert.name_ = ''Alert'' WHERE (hiproinst.start_time_ between :StartDate AND  :EndDate ) AND hiproinst.state_ != ''EXTERNALLY_TERMINATED'' AND hiproinst.proc_def_key_ = :CaseType AND hiproinst.tenant_id_ = :tenantidstr LIMIT 25000;",
        "Closed": "SELECT CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ IS NOT NULL THEN clsuser.email_ ELSE ''Auto Closed'' END ELSE NULL END AS \\"Closed By\\", basedon.text_ AS \\"Alert Type\\", address.text_ AS \\"Address\\", hiproinst.end_time_ AS \\"Closed Date\\", CASE WHEN hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END AS \\"Stage\\", cuser.email_ AS \\"Claimed By\\", hiproinst.start_time_ AS \\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN ''Closed'' WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \\"Status\\", pdef.name_ AS \\"Case Type\\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \\"Claimed On\\", null AS \\"Payer\\", null AS \\"Payee\\", null AS \\"Amount\\", ticketid.long_ AS \\"Case ID\\", alert.text_ AS \\"Alert\\" FROM camunda.act_hi_procinst hiproinst left OUTER JOIN camunda.act_re_procdef pdef ON pdef.id_ = hiproinst.proc_def_id_ left OUTER JOIN camunda.act_ru_task task ON task.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN camunda.act_id_user cuser ON cuser.id_ = task.assignee_ FULL OUTER JOIN camunda.act_hi_detail oplog ON oplog.id_ = (SELECT id_ FROM camunda.act_hi_detail WHERE proc_inst_id_ = task.proc_inst_id_ AND name_ = ''userActivity'' ORDER BY time_ DESC LIMIT 1) FULL OUTER JOIN camunda.act_hi_taskinst closedby ON closedby.id_ = (SELECT id_ FROM camunda.act_hi_taskinst WHERE proc_inst_id_ = hiproinst.proc_inst_id_ ORDER BY end_time_ DESC LIMIT 1) LEFT JOIN camunda.act_id_user clsuser ON clsuser.id_ = closedby.assignee_ left JOIN camunda.act_hi_varinst basedon ON basedon.proc_inst_id_ = hiproinst.proc_inst_id_ AND basedon.name_ = ''basedon'' left JOIN camunda.act_hi_varinst address ON address.proc_inst_id_ = hiproinst.proc_inst_id_ AND address.name_ = ''address'' FULL OUTER JOIN camunda.act_hi_varinst ticketid ON ticketid.proc_inst_id_ = hiproinst.proc_inst_id_ AND ticketid.name_ = ''TicketID'' FULL OUTER JOIN camunda.act_hi_varinst alert ON alert.proc_inst_id_ = hiproinst.proc_inst_id_ AND alert.name_ = ''Alert'' WHERE (hiproinst.start_time_ between :StartDate AND  :EndDate ) AND hiproinst.state_ = ''COMPLETED'' AND hiproinst.proc_def_key_ = :CaseType AND hiproinst.tenant_id_ = :tenantidstr LIMIT 25000;"
   }
 }'::text WHERE
