UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "Initial": {
        "All": "WITH d1 AS ( SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND iorgid = :orgid AND mappingtype = ''TransactionClass''), transaction_classes AS ( SELECT vcclassname, skipprocessing FROM ui.transactionclasses WHERE (iclassid IN (SELECT mappingid FROM d1) OR -1 IN (SELECT mappingid FROM d1))  AND itenantid = :tenantid ) select result->''score''->>''decisiondetails'' as \\"decisiondetails\\", ilivemessageid as \\"ILiveMessageID\\", vcmsgid as \\"UniqueID\\", vcclassname as \\"Class\\", dttrxntime  as \\"Time\\", dobservationamount as \\"Amount\\", score as \\"Score\\",  case when result->>''status''=''Failed'' then ''false'' when result->>''status''=''Success'' then ''true'' when result->>''status'' IS NULL then CASE WHEN score > 0 THEN ''false'' WHEN score = 0  THEN ''true'' else NULL end end as \\"FRMPass\\", vcpayeraccountexternalid as \\"Payer Account\\", vcpayeraddr as \\"PayerVPA\\", vcpayeeaccountexternalid as \\"Payee Account\\", vcpayeeaddr as \\"PayeeVPA\\", null as \\"FailedRule\\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \\"PayerName\\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as  \\"PayeeName\\", cast(observations-> ''txn''->>''type'' as text) as \\"Txn Type\\", ipayeemccid as \\"Payee MCC\\",cast(observations-> ''txn''->''attribs''->''skip_processing'' as int) as \\"Skip Processing\\" FROM analytics.trans WHERE vcclassname IN (SELECT vcclassname FROM transaction_classes ) AND (score >= :score OR vcclassname IN ( SELECT vcclassname FROM transaction_classes WHERE skipprocessing = -2 ) ) AND dtcreateddatetime BETWEEN ((CURRENT_TIMESTAMP - INTERVAL ''5 minutes'') AT TIME ZONE :timeZone) AND CURRENT_TIMESTAMP AT TIME ZONE :timeZone  AND itenantid = :tenantid ORDER BY ilivemessageid DESC LIMIT 50;",
        "Other": "WITH transaction_classes AS ( SELECT vcclassname, skipprocessing FROM ui.transactionclasses WHERE vcclassname = :className  AND itenantid = :tenantid ) select result->''score''->>''decisiondetails'' as \\"decisiondetails\\", ilivemessageid as \\"ILiveMessageID\\", vcmsgid as \\"UniqueID\\", vcclassname as \\"Class\\", dttrxntime  as \\"Time\\", dobservationamount as \\"Amount\\", score as \\"Score\\",  case when result->>''status''=''Failed'' then ''false'' when result->>''status''=''Success'' then ''true'' when result->>''status'' IS NULL then CASE WHEN score > 0 THEN ''false'' WHEN score = 0  THEN ''true'' else NULL end end as \\"FRMPass\\", vcpayeraccountexternalid as \\"Payer Account\\", vcpayeraddr as \\"PayerVPA\\", vcpayeeaccountexternalid as \\"Payee Account\\", vcpayeeaddr as \\"PayeeVPA\\", null as \\"FailedRule\\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \\"PayerName\\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as  \\"PayeeName\\", cast(observations-> ''txn''->>''type'' as text) as \\"Txn Type\\", ipayeemccid as \\"Payee MCC\\",cast(observations-> ''txn''->''attribs''->''skip_processing'' as int) as \\"Skip Processing\\" FROM analytics.trans WHERE vcclassname IN (SELECT vcclassname FROM transaction_classes ) AND (score >= :score OR vcclassname IN ( SELECT vcclassname FROM transaction_classes WHERE skipprocessing = -2 ) ) AND dtcreateddatetime BETWEEN ((CURRENT_TIMESTAMP - INTERVAL ''5 minutes'') AT TIME ZONE :timeZone) AND CURRENT_TIMESTAMP AT TIME ZONE :timeZone  AND itenantid = :tenantid ORDER BY ilivemessageid DESC LIMIT 50;"
    },
